-- =====================================================================
-- RESCURA — SIMULATED Chennai demonstration data
-- Generated by scripts/generate-seed-sql.ts (do not edit by hand).
-- All names, phone numbers, readings, incidents, teams and shelters are fictional samples.
-- Run AFTER supabase/migrations/0001_init.sql.
-- =====================================================================
begin;

truncate public.activity_log, public.rescue_assignments, public.sos_status_events, public.sos_requests,
  public.flood_reports, public.disaster_alerts, public.shelter_facilities, public.shelters,
  public.rainfall_readings cascade;

on conflict (id) do update set name = excluded.name, lat = excluded.lat, lng = excluded.lng, radius_m = excluded.radius_m,
  population = excluded.population, historical_susceptibility = excluded.historical_susceptibility,
  elevation_m = excluded.elevation_m, drainage_note = excluded.drainage_note;


on conflict (id) do update set name = excluded.name, agency = excluded.agency, team_type = excluded.team_type,
  base_zone_id = excluded.base_zone_id, lat = excluded.lat, lng = excluded.lng, members = excluded.members,
  contact = excluded.contact, status = excluded.status, capabilities = excluded.capabilities;






update public.sos_status_events e set created_at = s.created_at
  from public.sos_requests s where e.sos_id = s.id and e.status = 'submitted';
select setval('public.sos_reference_seq', 1041);




commit;

