insert into public.risk_zones (id, name, lat, lng, radius_m, population, historical_susceptibility, elevation_m, drainage_note) values
  ('velachery', 'Velachery', 12.9815, 80.218, 1450, 245000, 0.9, 6, 'Low-lying area on former wetland that drains toward the Pallikaranai marsh.'),
  ('tambaram', 'Tambaram', 12.9249, 80.117, 1700, 230000, 0.7, 28, 'Surrounded by lakes whose surplus water can overflow into residential streets.'),
  ('adyar', 'Adyar', 13.0063, 80.2574, 1350, 190000, 0.6, 8, 'Adjoins the Adyar river; high river levels can cause backflow into drains.'),
  ('saidapet', 'Saidapet', 13.0213, 80.2231, 1200, 160000, 0.65, 10, 'Riverside settlements along the Adyar river are exposed when water levels rise.'),
  ('perungudi', 'Perungudi', 12.9654, 80.2461, 1350, 120000, 0.55, 7, 'IT-corridor area draining to the Buckingham Canal; service roads collect water.'),
  ('pallikaranai', 'Pallikaranai', 12.9349, 80.2137, 1550, 110000, 0.85, 5, 'Built around the Pallikaranai marshland catchment; slow to drain.'),
  ('madipakkam', 'Madipakkam', 12.9647, 80.1961, 1250, 135000, 0.75, 9, 'Residential low-lying pockets that receive lake surplus during heavy spells.'),
  ('tnagar', 'T. Nagar', 13.0418, 80.2341, 1100, 210000, 0.35, 11, 'Dense commercial area; subways and underpasses are prone to waterlogging.')
