insert into public.disaster_alerts (id, title, message, level, zone_ids, instructions, issued_at, issued_by_name, source, active) values
  ('al-1', 'Heavy rainfall alert for south Chennai', 'Heavy to very heavy rainfall is expected over the next 24 hours (simulated forecast). Low-lying areas may experience waterlogging.', 'orange', array['velachery', 'pallikaranai', 'madipakkam', 'tambaram', 'perungudi']::text[], array['Move to higher floors or higher ground if water enters your home.', 'Switch off the main electricity supply if water reaches switchboards.', 'Do not walk or drive through floodwater deeper than 30 cm.', 'Keep phones charged and an emergency kit (water, medicines, torch, documents) ready.', 'Follow instructions from officials and use the SOS button only for emergencies.']::text[], now() - interval '180 minutes', 'District Emergency Operations Centre (sample)', 'official', true),
  ('al-2', 'Avoid subways and underpasses', 'Waterlogging reported at several subways. Use alternate routes and avoid driving through standing water.', 'yellow', array['tnagar', 'saidapet', 'tambaram']::text[], array['Avoid subways and underpasses until water is pumped out.', 'Do not drive through water deeper than 30 cm.', 'Report waterlogged roads using the resident portal.']::text[], now() - interval '140 minutes', 'Traffic Control Room (sample)', 'official', true),
  ('al-3', 'Moderate rain watch', 'Moderate rain expected through the evening (simulated).', 'yellow', array['adyar', 'saidapet', 'tnagar']::text[], array['Stay updated through official channels.']::text[], now() - interval '1200 minutes', 'District Emergency Operations Centre (sample)', 'official', false);
insert into public.flood_reports (id, reporter_name, zone_id, road_name, description, severity, water_depth_cm, lat, lng, path, status, created_at) values
  ('fr-1', 'Meena Krishnan', 'velachery', 'Velachery Main Road (Vijayanagar junction)', 'Knee-deep water across both lanes, two-wheelers stalling.', 'moderate', 45, 12.9792, 80.2196, '[[12.9762,80.2214],[12.9792,80.2196],[12.9824,80.2181]]'::jsonb, 'verified', now() - interval '50 minutes'),
  ('fr-2', 'Abdul Rahman', 'tambaram', 'GST Road subway', 'Subway fully submerged; traffic diverted.', 'severe', 95, 12.9246, 80.1168, '[[12.9229,80.1152],[12.9246,80.1168],[12.9263,80.1183]]'::jsonb, 'verified', now() - interval '85 minutes'),
  ('fr-3', 'Field staff – Zone 14', 'pallikaranai', 'Velachery–Tambaram Main Road (Pallikaranai stretch)', 'Water flowing across the road from the marsh side.', 'moderate', 40, 12.9352, 80.2108, '[[12.9398,80.2122],[12.9352,80.2108],[12.9303,80.2093]]'::jsonb, 'reported', now() - interval '95 minutes'),
  ('fr-4', 'Karthik S', 'perungudi', 'OMR service road near Perungudi', 'Service road waterlogged, main carriageway passable.', 'moderate', 35, 12.9658, 80.2478, '[[12.9638,80.2474],[12.9658,80.2478],[12.9679,80.2483]]'::jsonb, 'reported', now() - interval '120 minutes'),
  ('fr-5', 'Nisha P', 'saidapet', 'Jones Road, Saidapet', 'Ankle-deep water near the market.', 'low', 20, 13.0221, 80.2219, null, 'reported', now() - interval '140 minutes'),
  ('fr-6', 'Traffic police (sample)', 'tnagar', 'Usman Road subway approach', 'Water collecting at the subway approach; pumps operating.', 'low', 25, 13.0395, 80.2329, null, 'verified', now() - interval '150 minutes'),
  ('fr-7', 'Ramesh K', 'madipakkam', 'Ram Nagar Main Road', 'Low-lying stretch with standing water.', 'low', 20, 12.9655, 80.1975, null, 'reported', now() - interval '170 minutes');
insert into public.sos_requests (id, reference, name, phone, emergency_type, urgency, description, people_count, zone_id, landmark, lat, lng, status, assigned_team_id, created_at, updated_at) values
  ('sos-1041', 'SOS-1041', 'Meena Krishnan', '+91 90000 20002', 'evacuation', 'medium', 'Water entering ground floor. Two elderly parents need help moving to a relief centre.', 3, 'velachery', 'Near Vijayanagar bus stand', 12.9788, 80.2208, 'submitted', null, now() - interval '35 minutes', now() - interval '35 minutes'),
  ('sos-1038', 'SOS-1038', 'Abdul Rahman', '+91 90000 20003', 'trapped', 'high', 'Car stalled inside the flooded subway, two people unable to get out safely.', 2, 'tambaram', 'GST Road subway', 12.9243, 80.1162, 'assigned', 'team-3', now() - interval '70 minutes', now() - interval '55 minutes'),
  ('sos-1036', 'SOS-1036', 'Lakshmi Narayanan', '+91 90000 20004', 'medical', 'critical', 'Dialysis patient needs transport to hospital; street is under knee-deep water.', 1, 'pallikaranai', 'Behind Pallikaranai panchayat office', 12.9362, 80.2112, 'in_progress', 'team-5', now() - interval '125 minutes', now() - interval '80 minutes'),
  ('sos-1033', 'SOS-1033', 'John Peter', '+91 90000 20005', 'food_water', 'medium', 'Apartment complex cut off; around 40 residents need drinking water and food packets.', 40, 'adyar', 'Gandhi Nagar 2nd Main Road', 13.0045, 80.2598, 'submitted', null, now() - interval '160 minutes', now() - interval '160 minutes'),
  ('sos-1030', 'SOS-1030', 'Ravi Shankar', '+91 90000 20006', 'evacuation', 'high', 'Riverside huts flooding, families with children need evacuation.', 18, 'saidapet', 'Riverside, near Saidapet bridge', 13.0197, 80.2268, 'resolved', 'team-2', now() - interval '300 minutes', now() - interval '190 minutes'),
  ('sos-1029', 'SOS-1029', 'Sowmya Iyer', '+91 90000 20007', 'electrical', 'high', 'Electric line has fallen into a waterlogged street; risk of electrocution.', 6, 'perungudi', 'Kandanchavadi, OMR service road', 12.9662, 80.2472, 'resolved', 'team-4', now() - interval '330 minutes', now() - interval '240 minutes');
